head.script:
// 테스트 설명, 유효성 값 설정
//  - _1 : 사용자 입력 / 편집 완료, noResult, emptyValue, ref 바인딩 축
//  - _2 : setValue() / ref 와 valueNotInList 축, _3 : 처음 렌더링(emptyIndex) / 아이템 리스트 갱신(placeholder) 축
scwin.tData = {
    "description" : "[autoComplete > P > emptyItem]<br/>아이템 리스트에 없는 값이 설정되거나 입력되었을때 처리하는 방식을 설정합니다.",
    "validation" : [
        "emptyItem='true' 이면 noResult='clear' 로 동작합니다.",
        "true 설정 시, 설정하거나 입력한 값이 아이템 리스트에 없으면 아이템이 선택되지 않은 상태로 처리됩니다.",
        "true 설정 시, 입력창에는 빈 값이 표시되고 Value 는 emptyValue 속성값이 적용됩니다.",
        "false 설정 시, 사용자가 입력하거나 ref 속성으로 바인딩된 데이터가 아이템 리스트에 없으면 noResult 속성값에 따라 처리됩니다.",
        "미설정 시, 사용자가 입력하거나 ref 속성으로 바인딩된 데이터가 아이템 리스트에 없으면 noResult 속성값에 따라 처리됩니다.",
        "사용자가 아이템에 없는 값을 입력하고 편집을 완료하면 빈 값으로 표시되며 getValue() 메소드는 emptyValue 속성값을 반환합니다.",
        "ref 속성으로 바인딩된 경우 아이템이 선택되지 않은 상태로 처리되면 바인딩된 DataCollection 의 값도 emptyValue 속성값으로 변경됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // ref 바인딩 대상 DataMap 생성
    let strDm = '';
    strDm += '<w2:dataMap ' + $c.gcm.getNameSpace() + ' baseNode="map" id="dm_ref">';
    strDm += '<w2:keyInfo>';
    strDm += '<w2:key id="city" name="city" dataType="text"></w2:key>';
    strDm += '</w2:keyInfo>';
    strDm += '</w2:dataMap>';
    $p.data.create(strDm);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (emptyItem=true, noResult 미설정, ref 바인딩)
    con_emptyItem.setValue("2");
    con_noResult.setSelectedIndex(0);
    con_ref.setSelectedIndex(1);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
//  - 아이템은 정적 item 으로 정의 (Seoul / SEL, Busan / PUS, Incheon / ICN, Jeju / CJU)
//  - 초기 값은 Busan (PUS) : ref 바인딩이면 DataMap city 초기값, 아니면 생성 후 setValue
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(Label / Value) : Seoul / SEL, Busan / PUS, Incheon / ICN, Jeju / CJU\n- Target 재생성 시 초기 값은 Busan (PUS), ref 바인딩이면 DataMap(dm_ref) 의 city 에 바인딩\n[절차]\n1. 조건 선택 -> Target 재생성\n2. target1 의 값 표시 영역 클릭 -> 입력값을 지우고 Daegu 입력 -> Enter 키 (또는 화면 빈 곳 클릭) -> 상태 확인\n3. Target 재생성 -> value 입력 -> setValue 또는 ref 데이터 변경(ref 바인딩일 때) (결과 자동 출력)\n[확인] 선택 인덱스 / getValue / 표시값 / DataMap city 값"', '', 'label1');

    // 미설정 옵션은 속성 자체를 넣지 않는다 (createCList 가 빈값 키 제외, gdl_boolean 은 getText 로 읽는다)
    let bRef = con_ref.getValue() === "bind";
    let properties = {
        emptyItem : con_emptyItem.getText(),
        noResult : con_noResult.getValue(),
        emptyValue : con_emptyValue.getValue(),
        ref : bRef ? "data:dm_ref.city" : "",
    }

    let cList = $c.gcm.createCList(properties);

    // 재생성할 때마다 같은 상태에서 시작하도록 바인딩 값 초기화
    dm_ref.set("city", bRef ? "PUS" : "");

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>Seoul</w2:label><w2:value>SEL</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Busan</w2:label><w2:value>PUS</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Incheon</w2:label><w2:value>ICN</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Jeju</w2:label><w2:value>CJU</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    let objTarget = await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());

    if (objTarget && !bRef) {
        target1.setValue("PUS");
    }
};



// 선택 인덱스 / getValue / 표시값 (+ ref 바인딩이면 DataMap city 값) 한 줄 출력
//  - 표시값 : 편집 모드가 아닐 때 보이는 값 표시 영역의 글자
scwin.printState = function (strPrefix) {
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    let strResult = strPrefix + "선택 인덱스 : " + target1.getSelectedIndex() + " / getValue : " + target1.getValue() + " / 표시값 : '" + labelElem.textContent + "'";
    if (con_ref.getValue() === "bind") {
        strResult += " / DataMap city : " + dm_ref.get("city");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(strResult);
};



// 입력 후 편집 완료 상태 출력 (validation 1 ~ 8)
scwin.btn_getState_onclick = function (e) {
    scwin.printState("");
};



// setValue 로 아이템에 없는 값 설정 후 상태 출력 (validation 2, 3)
scwin.btn_setValue_onclick = function (e) {
    let strValue = par_value.getValue();
    target1.setValue(strValue);
    scwin.printState("setValue(" + strValue + ") -> ");
};



// 바인딩된 DataMap 값 변경 후 상태 출력 (validation 2 ~ 5, 8) - ref 바인딩일 때만 동작
scwin.btn_setRefData_onclick = function (e) {
    let strValue = par_value.getValue();
    if (con_ref.getValue() !== "bind") {
        return;
    }
    dm_ref.set("city", strValue);
    scwin.printState("DataMap city = " + strValue + " -> ");
};
